            if artifact_digest "'!= self.digest {
                return Err(crate::admission::ArtifactEnvelopeError::ArtifactNotFound {
                    digest: artifact_digest,
                });
            }
            let contract = ActionContract {
                id: CoreActionId::new(0),
                name: ActionName::new("recovery-action").unwrap(),
                input_slot_count: 0,
                output_slot_count: 1,
                max_input_bytes: 0,
                max_output_bytes: 1024,
                timeout_ms: 5000,
                idempotency: Idempotency::DeterministicPure,
                side_effect: SideEffect::None,
                retry_safety: RetrySafety::Safe,
                required_capabilities: Box::new([]),
            };
            Ok(AcceptedArtifact {
                digest: self.digest,
                source_digest: self.digest,
                policy_digest: self.digest,
                ir: Vec::new(),
                verification: vb_storage::admission::VerificationProof {
                    digest: self.digest,
                    gate_count: 8,
                    durable: true,
                    bounded_claimed: true,
                    taint_safe_claimed: true,
                    retry_safe_claimed: true,
                    idempotency_verified_claimed: true,
                    replayable_claimed: true,
                    idempotency_keyed: Box::new([]),
                    idempotency_attested: Box::new([]),
                    warnings: Vec::new(),
                },
                accepted_at_seq: EventSeq::new(0),
                required_capabilities: Box::new([]),
                action_contracts: Box::from([contract]),
            })
        }
    }

    Arc::new(ContractStore { digest })
}

